mapper.select:
SELECT * FROM ( SELECT E1.*, ROWNUM AS RNUM FROM ( SELECT er.id AS EXPENSE_ID, m.challenge_id AS CHALLENGE_ID, er.meeting_id AS MEETING_ID, er.created_by AS CREATED_BY, u.nickname AS CREATED_BY_NICKNAME, u.profile_image_url AS CREATED_BY_PROFILE_IMAGE, er.title AS TITLE, er.amount AS AMOUNT, er.description AS DESCRIPTION, er.receipt_url AS RECEIPT_URL, er.status AS STATUS, er.created_at AS CREATED_AT, er.approved_at AS APPROVED_AT FROM woorido.expense_requests er JOIN woorido.meetings m ON er.meeting_id = m.id LEFT JOIN woorido.users u ON er.created_by = u.id WHERE m.challenge_id = #{challengeId}
AND er.status = #{status}
ORDER BY er.created_at DESC ) E1 WHERE ROWNUM <= #{offset} + #{limit} ) WHERE RNUM > #{offset}

SELECT COUNT(*)
FROM woorido.expense_requests er
JOIN woorido.meetings m ON er.meeting_id = m.id
WHERE m.challenge_id = #{challengeId}

    AND er.status = #{status}

SELECT NVL(SUM(er.amount), 0)
FROM woorido.expense_requests er
JOIN woorido.meetings m ON er.meeting_id = m.id
WHERE m.challenge_id = #{challengeId}

    AND er.status = #{status}

